#include <iostream>
#include <vector>
#include <queue>
using namespace std;

void bfs(vector<vector<int>> &graph, vector<bool> &visited, int node){
    queue<int> q;
    if (!visited[node]) {
        q.push(node);
        visited[node] = true;
    }
    while (!q.empty()) {
        int n = q.front();
        cout << n << " ";
        q.pop();
        for (auto neigh : graph[n]) {
            if (!visited[neigh]) {
                visited[neigh] = true;
                q.push(neigh);
            }
        }
    }
}

void dfs(vector<vector<int>> &graph, vector<bool> &visited, int node) {
    if (visited[node]) {
        return;
    }
    visited[node] = true;
    cout << node << " ";

    for (auto neigh : graph[node]) {
        dfs(graph, visited, neigh);
    }
}

int main() {

    int n = 7;

    vector<vector<int>> graph(n);

    // Directed graph
    graph[0].push_back(1);
    graph[0].push_back(2);

    graph[1].push_back(3);
    graph[1].push_back(4);

    graph[2].push_back(5);

    graph[4].push_back(5);

    graph[5].push_back(6);

    vector<bool> visited(n, false);

    cout << "DFS\n\n\n";
    dfs(graph, visited, 0);
    vector<bool> visited2(n, false);
    cout << "\n\n\nBFS\n\n\n";
    bfs(graph, visited2, 0);

    return 0;
}
